	model := c.sourceDirectModel(c.facts.Type(specification.Type))
	if model != nil {
		c.reportResult(
			syntax.ExpressionPosition(specification.Type),
			"cannot define a new type from %s; use an alias",
			modelName(model),
		)
	}
